class Glow:Form {
 protected override bool ShowWithoutActivation {get{return true;}}
 protected override CreateParams CreateParams {get{var p=base.CreateParams;p.ExStyle|=0x20|0x80000|0x8000000|0x80;return p;}}
 public Glow(Rectangle r){FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;TopMost=true;StartPosition=FormStartPosition.Manual;Bounds=r;}
}
class Session {
 public double Seconds;public double Duration=1800;public bool Running,Visible; public void Start(double duration){Duration=duration;Seconds=0;Play();} public Color CurrentColor {get{return ColorAt(Seconds/Duration*1800);}}
 public void Play(){if(Seconds>=Duration)Seconds=0;Running=true;Visible=true;}
 public void Pause(){Running=false;}
 public void Stop(){Seconds=0;Duration=1800;Running=false;Visible=false;}
 public void Advance(double seconds){if(Running){Seconds=Math.Min(Duration,Seconds+Math.Max(0,seconds));if(Seconds>=Duration)Running=false;}}
 public static Color ColorAt(double seconds){double p=Math.Max(0,Math.Min(3,seconds/600));Color[] c={Color.FromArgb(255,220,0),Color.FromArgb(255,110,0),Color.FromArgb(255,0,0),Color.FromArgb(110,0,0)};int i=Math.Min(2,(int)p);double t=p-i;return Color.FromArgb((int)Math.Round(c[i].R+(c[i+1].R-c[i].R)*t),(int)Math.Round(c[i].G+(c[i+1].G-c[i].G)*t),0);}
}
