 void Translate(){test3.Text=T("Test — 3 minuten","Test — 3 minutes");test30.Text=T("Test 2 — 30 seconden","Test 2 — 30 seconds");subtitle.Text=T("1.0-dev • B • Alleen handmatig testen","1.0-dev • B • Manual test only");description.Text=T("30 minuten: geel → oranje → rood → donkerrood","30 minutes: yellow → orange → red → dark red");pause.Text=T("Ⅱ Pauze","Ⅱ Pause");stop.Text="■ Stop";save.Text=T("Opslaan","Save");hint.Text=T("Pauze houdt tijd en kleur vast. Stop verwijdert de gloed. Aan het einde blijft donkerrood staan tot Stop. Geen automatische start. Minimaliseer naar het systeemvak.","Pause freezes time and color. Stop removes the glow. At the end dark red stays until Stop. No automatic start. Minimize to the system tray.");saved.Text="";BuildMenu();Apply();}
 void Apply(){Color c=session.CurrentColor;swatch.BackColor=c;progress.Maximum=(int)session.Duration;progress.Value=(int)session.Seconds;elapsed.Text=TimeSpan.FromSeconds(session.Seconds).ToString(@"mm\:ss")+" / "+TimeSpan.FromSeconds(session.Duration).ToString(@"mm\:ss");amount.Text=T("Sterkte: ","Strength: ")+strength.Value+"%";state.Text=session.Running?T("● Speelt","● Playing"):!session.Visible?T("○ Gestopt — druk op Play","○ Stopped — press Play"):session.Seconds>=session.Duration?T("● Voltooid — donkerrood blijft actief","● Complete — dark red remains active"):T("Ⅱ Gepauzeerd — kleur blijft actief","Ⅱ Paused — color remains active");play.Enabled=!session.Running;play.Text=session.Visible&&!session.Running&&session.Seconds<session.Duration?T("▶ Hervatten","▶ Resume"):"▶ Play";pause.Enabled=session.Running;stop.Enabled=session.Visible;foreach(var button in new[]{play,pause,stop,save,test3,test30}){button.BackColor=button.Enabled?Color.FromArgb(245,247,250):Color.FromArgb(180,187,199);button.ForeColor=Color.FromArgb(18,24,35);button.FlatAppearance.BorderColor=button.Enabled?Color.White:Color.FromArgb(140,150,166);}if(testing)return;if(session.Visible&&glows.Count==0)foreach(var screen in Screen.AllScreens)glows.Add(new Glow(screen.Bounds));foreach(var g in glows){g.BackColor=c;g.Opacity=strength.Value/100.0;if(session.Visible){if(!g.Visible)g.Show();g.TopMost=true;}else g.Hide();}}
