 static void Check(bool b,string n){if(!b)throw new Exception(n);}
 static void Test(){Data=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-settings.txt");if(File.Exists(Data))File.Delete(Data);var s=new Session();Check(!s.Visible&&!s.Running,"Manual startup");s.Play();s.Advance(60);Check(s.Seconds==60,"Minute progress");s.Pause();s.Advance(100);Check(s.Seconds==60&&s.Visible,"Pause freeze");s.Play();s.Advance(1740);Check(s.Seconds==1800&&!s.Running&&s.Visible,"30 minute end hold");s.Play();Check(s.Seconds==0&&s.Running,"Replay");s.Stop();Check(!s.Visible&&s.Seconds==0,"Stop");Check(Session.ColorAt(0)==Color.FromArgb(255,220,0)&&Session.ColorAt(600)==Color.FromArgb(255,110,0)&&Session.ColorAt(1200)==Color.FromArgb(255,0,0)&&Session.ColorAt(1800)==Color.FromArgb(110,0,0),"Color anchors");for(int i=1;i<=30;i++)Check(Session.ColorAt(i*60)!=Session.ColorAt((i-1)*60),"Every minute changes color");
 foreach(double duration in new[]{180.0,30.0}){s.Start(duration);Check(s.CurrentColor==Session.ColorAt(0),"Test starts yellow");s.Advance(duration/3);Check(s.CurrentColor==Session.ColorAt(600),"Test orange");s.Pause();s.Advance(50);Check(s.Seconds==duration/3,"Test pause");s.Play();s.Advance(duration/3);Check(s.CurrentColor==Session.ColorAt(1200),"Test red");s.Advance(duration/3);Check(s.Seconds==duration&&!s.Running&&s.CurrentColor==Session.ColorAt(1800),"Test dark red endpoint");s.Stop();Check(s.Duration==1800&&!s.Visible,"Normal mode restored");}
 using(var f=new Sunset(true)){f.Show();Application.DoEvents();f.play.PerformClick();Check(f.session.Running,"Play button");f.pause.PerformClick();Check(!f.session.Running&&f.session.Visible,"Pause button");f.stop.PerformClick();Check(!f.session.Visible,"Stop button");f.test3.PerformClick();Check(f.session.Duration==180&&f.session.Running,"3 minute test button");f.test30.PerformClick();Check(f.session.Duration==30&&f.session.Seconds==0,"30 second test button restart");f.stop.PerformClick();foreach(int lang in new[]{0,1}){f.language.SelectedIndex=lang;Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,lang==0?"preview-nl.png":"preview-en.png"));}}f.strength.Value=32;f.save.PerformClick();}using(var f=new Sunset(true)){Check(f.English&&f.strength.Value==32&&!f.session.Visible,"Persistence without auto start");}File.Delete(Data);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"),"PASS: 3-minute and 30-second test buttons, color anchors at both speeds, test pause and stop, normal duration restored, play/pause/resume/stop/replay, 30-minute end, 31 color points, NL/EN rendering, language/strength persistence, no automatic startup. Full 30-minute live display not timed.");}
